-- ========================================
-- Verify Import
-- ========================================

SELECT COUNT(*) as total_rows FROM price_history;
-- Expected: 41,800

SELECT
    MIN(price_date) as first_date,
    MAX(price_date) as last_date,
    COUNT(DISTINCT etf_id) as etf_count
FROM price_history;
-- Expected: 2009-01-02, 2025-01-03, 50 ETFs

SELECT
    e.ticker_symbol,
    ph.price_date,
    ph.close_price,
    ph.volume
FROM price_history ph
JOIN etf_master e ON ph.etf_id = e.etf_id
ORDER BY ph.price_date DESC
LIMIT 10;
-- Shows latest 10 price records

